* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  width: 1280px; height: 800px;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex; align-items: center; justify-content: center;
  color: #fff;
  overflow: hidden;
}
.card {
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(20px);
  border-radius: 24px;
  padding: 48px 56px;
  width: 720px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.25);
  border: 1px solid rgba(255,255,255,0.2);
}
.location {
  font-size: 28px;
  font-weight: 300;
  opacity: 0.9;
  margin-bottom: 4px;
}
.date {
  font-size: 16px;
  opacity: 0.7;
  margin-bottom: 32px;
}
.main-info {
  display: flex;
  align-items: center;
  gap: 40px;
  margin-bottom: 36px;
}
.icon {
  font-size: 80px;
  line-height: 1;
}
.temps {
  flex: 1;
}
.temp-range {
  display: flex;
  gap: 24px;
  margin-bottom: 8px;
}
.temp-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.temp-label {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 1px;
  opacity: 0.7;
  margin-bottom: 4px;
}
.temp-value {
  font-size: 48px;
  font-weight: 700;
  line-height: 1;
}
.condition {
  font-size: 20px;
  font-weight: 400;
  opacity: 0.85;
}
.hourly-title {
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  opacity: 0.6;
  margin-bottom: 16px;
}
.hourly-scroll {
  overflow-x: auto;
  padding-bottom: 8px;
}
.hourly-scroll::-webkit-scrollbar { height: 6px; }
.hourly-scroll::-webkit-scrollbar-track { background: rgba(255,255,255,0.1); border-radius: 3px; }
.hourly-scroll::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.3); border-radius: 3px; }
.hourly {
  display: flex;
  gap: 6px;
  min-width: max-content;
}
.hour {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  border-radius: 12px;
  background: rgba(255,255,255,0.08);
  min-width: 56px;
  transition: background 0.2s;
}
.hour:hover { background: rgba(255,255,255,0.18); }
.hour-time { font-size: 12px; opacity: 0.6; margin-bottom: 6px; }
.hour-temp { font-size: 16px; font-weight: 600; }
.error-box {
  text-align: center;
  padding: 60px 40px;
}
.error-box .icon { font-size: 64px; margin-bottom: 20px; }
.error-box h2 { font-size: 24px; font-weight: 600; margin-bottom: 10px; }
.error-box p { font-size: 16px; opacity: 0.75; line-height: 1.5; }

(function(){
  const params = new URLSearchParams(location.search);
  const lat = params.get('lat') || '52.52';
  const lon = params.get('lon') || '13.405';
  const name = params.get('name') || 'Berlin';
  const now = new Date();
  const todayUTC = now.getUTCFullYear() + '-' +
    String(now.getUTCMonth()+1).padStart(2,'0') + '-' +
    String(now.getUTCDate()).padStart(2,'0');
  const date = params.get('date') || todayUTC;

  document.getElementById('loadName').textContent = name;

  const isPast = new Date(date + 'T00:00:00Z') < new Date(todayUTC + 'T00:00:00Z');
  const apiPath = isPast ? '/api/om/archive' : '/api/om/forecast';

  const qs = new URLSearchParams({
    latitude: lat,
    longitude: lon,
    daily: 'temperature_2m_max,temperature_2m_min,weather_code',
    hourly: 'temperature_2m',
    timezone: 'UTC',
    temperature_unit: 'celsius',
    start_date: date,
    end_date: date
  });

  const weatherDesc = {
    0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',
    45:'Fog',48:'Depositing rime fog',
    51:'Light drizzle',53:'Moderate drizzle',55:'Dense drizzle',
    56:'Light freezing drizzle',57:'Dense freezing drizzle',
    61:'Slight rain',63:'Moderate rain',65:'Heavy rain',
    66:'Light freezing rain',67:'Heavy freezing rain',
    71:'Slight snow',73:'Moderate snow',75:'Heavy snow',
    77:'Snow grains',
    80:'Slight rain showers',81:'Moderate rain showers',82:'Violent rain showers',
    85:'Slight snow showers',86:'Heavy snow showers',
    95:'Thunderstorm',96:'Thunderstorm with slight hail',99:'Thunderstorm with heavy hail'
  };

  const weatherIcon = {
    0:'☀️',1:'🌤️',2:'⛅',3:'☁️',
    45:'🌫️',48:'🌫️',
    51:'🌦️',53:'🌦️',55:'🌧️',56:'🌧️',57:'🌧️',
    61:'🌧️',63:'🌧️',65:'🌧️',66:'🌧️',67:'🌧️',
    71:'🌨️',73:'🌨️',75:'❄️',77:'🌨️',
    80:'🌦️',81:'🌧️',82:'⛈️',85:'🌨️',86:'🌨️',
    95:'⛈️',96:'⛈️',99:'⛈️'
  };

  const bgByCode = {
    0:'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)',
    1:'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',
    2:'linear-gradient(135deg, #89f7fe 0%, #66a6ff 100%)',
    3:'linear-gradient(135deg, #868f96 0%, #596164 100%)',
  };

  function getBg(code) {
    if (code <= 1) return bgByCode[code];
    if (code <= 3) return bgByCode[code];
    if (code >= 61 || code >= 51) return 'linear-gradient(135deg, #4b6cb7 0%, #182848 100%)';
    if (code >= 71) return 'linear-gradient(135deg, #e6dada 0%, #274046 100%)';
    if (code >= 95) return 'linear-gradient(135deg, #232526 0%, #414345 100%)';
    return 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)';
  }

  function showError(msg) {
    document.getElementById('card').innerHTML =
      '<div class="error-box"><div class="icon">⚠️</div><h2>Could not load weather data</h2><p>'+msg+'</p></div>';
  }

  fetch(apiPath + '?' + qs.toString())
    .then(r => { if (!r.ok) throw new Error('API returned status ' + r.status); return r.json(); })
    .then(data => {
      if (!data || !data.daily || !data.hourly) throw new Error('Unexpected response format');
      const dMax = data.daily.temperature_2m_max[0];
      const dMin = data.daily.temperature_2m_min[0];
      const code = data.daily.weather_code[0];
      const desc = weatherDesc[code] || 'Unknown (' + code + ')';
      const icon = weatherIcon[code] || '🌡️';
      const hourlyTemps = data.hourly.temperature_2m;

      document.body.style.background = getBg(code);

      const dateObj = new Date(date + 'T00:00:00Z');
      const dateStr = dateObj.toLocaleDateString('en-US', {
        weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC'
      });

      let hoursHTML = '';
      for (let i = 0; i < 24 && i < hourlyTemps.length; i++) {
        const h = String(i).padStart(2, '0') + ':00';
        hoursHTML += '<div class="hour"><span class="hour-time">' + h + '</span><span class="hour-temp">' + hourlyTemps[i].toFixed(1) + '°</span></div>';
      }

      document.getElementById('card').innerHTML =
        '<div class="location">' + name + '</div>' +
        '<div class="date">' + dateStr + '</div>' +
        '<div class="main-info">' +
          '<div class="icon">' + icon + '</div>' +
          '<div class="temps">' +
            '<div class="temp-range">' +
              '<div class="temp-item"><span class="temp-label">High</span><span class="temp-value">' + dMax.toFixed(1) + '°</span></div>' +
              '<div class="temp-item"><span class="temp-label">Low</span><span class="temp-value">' + dMin.toFixed(1) + '°</span></div>' +
            '</div>' +
            '<div class="condition">' + desc + '</div>' +
          '</div>' +
        '</div>' +
        '<div class="hourly-title">Hourly Temperatures</div>' +
        '<div class="hourly-scroll"><div class="hourly">' + hoursHTML + '</div></div>';
    })
    .catch(err => {
      showError('Failed to fetch weather data for <strong>' + name + '</strong> on <strong>' + date + '</strong>.<br>' + err.message);
    });
})();
